<?php
declare(strict_types=1);
namespace App\Repositories; use App\Core\Database;
final class BudgetRepository { public function all():array{$sql='SELECT b.*,c.name category_name,(SELECT COALESCE(SUM(e.amount),0) FROM expenses e WHERE e.expense_date BETWEEN b.start_date AND b.end_date AND e.status="posted" AND (b.category_id IS NULL OR e.category_id=b.category_id) AND e.user_id=b.user_id) spent FROM budgets b LEFT JOIN categories c ON c.id=b.category_id ORDER BY b.start_date DESC';return Database::connection()->query($sql)->fetchAll();} public function find(int $id):?array{$s=Database::connection()->prepare('SELECT * FROM budgets WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function create(array $d):int{$s=Database::connection()->prepare('INSERT INTO budgets(user_id,category_id,start_date,end_date,budget_amount,warning_thresholds,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$d['user_id'],$d['category_id']?:null,$d['start_date'],$d['end_date'],$d['budget_amount'],json_encode([75,90,100]),'active']);return (int)Database::connection()->lastInsertId();} public function delete(int $id):void{Database::connection()->prepare('DELETE FROM budgets WHERE id=?')->execute([$id]);}}
